CREATE TABLE pets (id Int64, age Int64, weight Int64 DEFAULT 1 COMMENT 'grams', CONSTRAINT positive CHECK id >= 0) ENGINE = MergeTree ORDER BY id;
ALTER TABLE pets ADD CONSTRAINT adult CHECK age >= 0;
CREATE MATERIALIZED VIEW pet_ids ENGINE = MergeTree ORDER BY id AS SELECT id FROM pets;
DROP TABLE pet_ids;
ALTER TABLE pets ADD COLUMN tag String DEFAULT 'none' AFTER id;
ALTER TABLE pets MODIFY COLUMN weight Float64;
ALTER TABLE pets MODIFY COLUMN age DEFAULT 0;
ALTER TABLE pets ADD COLUMN height Int64 DEFAULT 3;
ALTER TABLE pets MODIFY COLUMN height REMOVE DEFAULT;
